// Regenerates src/generated/*.ts from the forge build of contracts/src (solc 0.8.24, shanghai, optimizer 200, no metadata):
//   local-test-usd8.ts  LocalTestUSD8, the LOCAL test token of the Anvil demo
//   invoice-mandate.ts  InvoiceMandate, the on-chain vault the agent pays through when the mandate names one
// `--check` writes nothing and exits 1 when a generated file differs from the build (CI).
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');
const targets = [
  { contract: 'LocalTestUSD8', file: 'local-test-usd8.ts', prefix: 'LOCAL_TEST_USD8' },
  { contract: 'InvoiceMandate', file: 'invoice-mandate.ts', prefix: 'INVOICE_MANDATE' },
];
mkdirSync(join(root, 'src/generated'), { recursive: true });
let stale = 0;
for (const t of targets) {
  const artifact = JSON.parse(readFileSync(join(root, `contracts/out/${t.contract}.sol/${t.contract}.json`), 'utf8'));
  const text =
    `// Generated by npm run build:token (forge build of contracts/src/${t.contract}.sol, solc 0.8.24, optimizer 200, no metadata). Do not edit.\n` +
    `export const ${t.prefix}_ABI = ${JSON.stringify(artifact.abi)} as const;\n` +
    `export const ${t.prefix}_BYTECODE = ${JSON.stringify(artifact.bytecode.object)} as const;\n`;
  const path = join(root, 'src/generated', t.file);
  if (check) {
    const have = existsSync(path) ? readFileSync(path, 'utf8').replace(/\r\n/g, '\n') : '';
    if (have !== text) {
      console.error(`src/generated/${t.file} differs from the forge build: run npm run build:token`);
      stale++;
    }
    continue;
  }
  writeFileSync(path, text);
  console.log(`wrote src/generated/${t.file}`);
}
process.exitCode = stale ? 1 : 0;
